@DisplayName("판매 중인 상품만 조회된다")
@Test
void findSelling() {
    // given
    productRepository.saveAll(List.of(
            createProduct("001", SELLING, "아메리카노", 4000),
            createProduct("002", HOLD, "카페라떼", 4500),
            createProduct("003", STOP_SELLING, "팥빙수", 7000)));

    // when
    List<ProductResponse> products = productService.findSellingProducts();

    // then
    assertThat(products).hasSize(2)
            .extracting("productNumber", "sellingStatus")
            .containsExactlyInAnyOrder(
                    tuple("001", SELLING),
                    tuple("002", HOLD));
}

@DisplayName("신규 상품의 번호는 마지막 번호 + 1 이다")
@Test
void createProduct() {
    // given
    productRepository.save(createProduct("001", SELLING, "아메리카노", 4000));

    // when
    ProductResponse response = productService.createProduct(request);

    // then
    assertThat(response.getProductNumber()).isEqualTo("002");
}

